const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: Bearer token required for raw booking writer');
}

const payload = raw.body || raw;
if (!payload.start || !payload.end) throw new Error('Missing start/end');

let rawRes = payload.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const calendarId = payload.calendarId || 'ocompudoc@gmail.com';
const contact = payload.contact || {};
const displayName = contact.contactName || payload.contactName || 'Lead IA360';
const wa = contact.contactNumber || payload.contactNumber || '';
const summary = String(payload.summary || '').trim() || `IA360 diagnóstico - ${displayName}`;
const description = String(payload.description || '').trim() || `Reunión IA360 agendada desde WhatsApp. Contacto: ${displayName} (+${wa}).`;

return [{
  json: {
    ...payload,
    resources,
    needCalendar,
    needZoom,
    calendarId,
    displayName,
    wa,
    start: payload.start,
    end: payload.end,
    tz: 'America/Mexico_City',
    summary,
    description,
    zoomMeetingId: null,
    zoomJoinUrl: ''
  }
}];

const norm = $('Normalize Booking').first().json;
const zoom = $input.first() ? $input.first().json : {};
const zoomId = zoom.id || zoom.zoomMeetingId || null;
const zoomJoinUrl = zoom.join_url || zoom.zoomJoinUrl || '';

return [{
  json: {
    ...norm,
    zoomMeetingId: zoomId,
    zoomJoinUrl: zoomJoinUrl,
    zoom_raw: zoom
  }
}];

const raw = $input.first().json;
const meta = $('If Needs Calendar').first().json;
const busy = raw.calendars?.[meta.calendarId]?.busy || raw.busy || [];
if (busy.length > 0) throw new Error('slot_busy');
return [{ json: { ok: true, busy, ...meta } }];

const norm = $('Normalize Booking').first().json;
const resources = norm.resources || [];
const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const components = {};
let allVerified = true;

if (needZoom) {
  let zoomData = null;
  try { zoomData = $('Merge Zoom Info').first()?.json || $('Create Zoom Meeting').first()?.json; } catch (e) {}
  const zoomId = zoomData?.zoomMeetingId ? String(zoomData.zoomMeetingId) : (zoomData?.id ? String(zoomData.id) : null);
  const zoomJoinUrl = zoomData?.zoomJoinUrl || zoomData?.join_url || null;
  const zoomError = zoomData?.error?.message || zoomData?.error || null;

  const zoomVerified = Boolean(zoomId && zoomJoinUrl && String(zoomJoinUrl).startsWith('http'));
  if (zoomVerified) {
    components.zoom = {
      state: 'verified',
      id: zoomId,
      join_url: zoomJoinUrl
    };
  } else {
    allVerified = false;
    components.zoom = {
      state: zoomId ? 'uncertain' : 'failed',
      id: zoomId || undefined,
      join_url: zoomJoinUrl || undefined,
      error: zoomError || 'Zoom meeting was not verified by provider'
    };
  }
}

if (needCalendar) {
  let calData = null;
  try { calData = $('Verify Calendar Event Exists').first()?.json; } catch (e) {}
  if (!calData || !calData.id) {
    try { calData = $('Create Calendar Event').first()?.json; } catch (e) {}
  }
  const calId = calData?.id ? String(calData.id) : null;
  const calError = calData?.error?.message || calData?.error || null;
  const readStart = calData?.start?.dateTime || calData?.start?.date || '';
  const readEnd = calData?.end?.dateTime || calData?.end?.date || '';
  const readSummary = String(calData?.summary || '').trim();

  const startMatch = Boolean(readStart && new Date(readStart).toISOString() === new Date(norm.start).toISOString());
  const endMatch = Boolean(readEnd && new Date(readEnd).toISOString() === new Date(norm.end).toISOString());
  const titleMatch = Boolean(!norm.summary || readSummary === String(norm.summary).trim());
  const calVerified = Boolean(calId && startMatch && endMatch && titleMatch);

  if (calVerified) {
    components.calendar = {
      state: 'verified',
      id: calId,
      htmlLink: calData.htmlLink || undefined
    };
  } else {
    allVerified = false;
    components.calendar = {
      state: calId ? 'uncertain' : 'failed',
      id: calId || undefined,
      error: calError || (calId ? 'Calendar event slot/title mismatch' : 'READBACK_FAILED: Google Calendar event was not verified by readback')
    };
  }
}

const verified = Boolean(allVerified && resources.length > 0);

return [{
  json: {
    ok: verified,
    verified,
    status: verified ? 'booked' : 'uncertain',
    state: verified ? 'agendada' : 'incierta',
    resources,
    components,
    start: norm.start,
    end: norm.end,
    summary: norm.summary,
    contactName: norm.displayName,
    contactNumber: norm.wa,
    calendarEventId: components.calendar?.id || null,
    calendarHtmlLink: components.calendar?.htmlLink || null,
    zoomMeetingId: components.zoom?.id || null,
    zoomJoinUrl: components.zoom?.join_url || null
  }
}];
